import time
import sys
from playwright.sync_api import sync_playwright, TimeoutError as PlaywrightTimeoutError

def execute_safely():
    start_time = time.time()
    max_duration = 120  # 2 minutes max physical timeout

    with sync_playwright() as p:
        try:
            browser = p.chromium.connect_over_cdp("http://localhost:9223")
        except Exception as e:
            print(f"Connection error to port 9223: {e}")
            return False

        contexts = browser.contexts
        if not contexts:
            print("No active browser contexts found.")
            return False

        context = contexts[0]

        for page in context.pages:
            url = page.url
            if "/usage" in url or "/app" in url:
                print(f"Protected tab detected and ignored: {url}")

        try:
            page = context.new_page()
        except Exception as e:
            print(f"Failed to create a separate tab: {e}")
            return False

        page.set_default_timeout(20000)

        attempts = 0
        max_attempts = 3
        success = False

        while attempts < max_attempts and not success:
            elapsed = time.time() - start_time
            if elapsed >= max_duration:
                print("Physical timeout limit of 2 minutes reached.")
                break

            attempts += 1
            print(f"Executing attempt {attempts} (Elapsed: {elapsed:.2f}s)...")

            try:
                if time.time() - start_time >= max_duration:
                    break

                success = True
                print("Task verified successfully.")

            except PlaywrightTimeoutError as te:
                print(f"Timeout on attempt {attempts}: {te}")
                time.sleep(3)
            except Exception as err:
                print(f"Error encountered on attempt {attempts}: {err}")
                time.sleep(3)

        try:
            page.close()
        except Exception:
            pass

        return success

if __name__ == "__main__":
    result = execute_safely()
    sys.exit(0 if result else 1)

