from playwright.async_api import async_playwright

async def speak_text(text: str = "Hello, this is your requested text-to-speech output."):
    try:
        async with async_playwright() as p:
            # Connect to the existing browser instance on port 9223
            browser = await p.chromium.connect_over_cdp("http://localhost:9223")

            contexts = browser.contexts
            if not contexts:
                raise RuntimeError("No browser contexts found on port 9223.")

            context = contexts[0]

            # Inspect existing pages to ensure we don't touch forbidden tabs
            for page in context.pages:
                url = page.url
                if "/usage" in url or "/app" in url:
                    print(f"Skipping restricted tab: {url}")

            # Always open and use a separate new tab
            new_page = await context.new_page()
            try:
                await new_page.goto("about:blank")

                # Execute Web Speech API inside the browser tab
                await new_page.evaluate(f"""
                    () => {{
                        return new Promise((resolve, reject) => {{
                            if (!('speechSynthesis' in window)) {{
                                reject(new Error('Speech synthesis not supported in this browser context.'));
                                return;
                            }}
                            const utterance = new SpeechSynthesisUtterance({repr(text)});
                            utterance.onend = () => resolve();
                            utterance.onerror = (e) => reject(new Error(e.error));
                            window.speechSynthesis.speak(utterance);
                        }});
                    }}
                """)
                print("Speech synthesis completed successfully.")
            finally:
                await new_page.close()

    except asyncio.TimeoutError:
        print("Error: Script exceeded the 2-minute physical timeout limit.")
    except Exception as e:
        print(f"Error encountered during execution: {e}")
        raise e

if __name__ == "__main__":
    # Enforce a strict 2-minute max physical timeout (120 seconds)
    asyncio.run(asyncio.wait_for(speak_text("Hello! Speaking to you now via the connected browser instance."), timeout=120))

