    prompt_1 = "Write a valid Python script that performs a simple utility task and is strictly less than 7 lines long. Output only executable python code without markdown formatting."

    code_1 = call_llm(prompt_1).strip()
    if code_1.startswith("```python"):
        code_1 = code_1[9:]
    if code_1.endswith("```"):
        code_1 = code_1[:-3]
    code_1 = code_1.strip()

    line_count_1 = len(code_1.splitlines())
    print(f"Stage 1 Code ({line_count_1} lines):\n{code_1}\n")

    success_1, stdout_1, stderr_1 = run_code_safely(code_1)
    if not success_1 or line_count_1 >= 7:
        print(f"Verification failed for Stage 1. Error: {stderr_1}")
        return

    print("Stage 1 verified successfully. Proceeding to Stage 2...")

    prompt_2 = f"The previous code was successfully verified (under 7 lines). Now, write a more comprehensive Python script that is strictly more than 7 lines long. Output only executable python code without markdown formatting.\nPrevious code:\n{code_1}"

    code_2 = call_llm(prompt_2).strip()
